def gen(rng):
    def fmt(words, chars):
        return str(len(words)) + '\n' + '\n'.join(words) + '\n' + chars
    def rw(alpha, lo, hi):
        return ''.join(rng.choice(alpha) for _ in range(rng.randint(lo, hi)))
    tests = [
        fmt(['a'], 'a'),
        fmt(['a'], 'b'),
        fmt(['aa'], 'a'),
        fmt(['abc', 'abc', 'abc'], 'cba'),
        fmt(['zzzzzzzzzzzzzzz'], 'z' * 15),
        fmt(['zzzzzzzzzzzzzzz'], 'z' * 14),
        fmt(['b', 'a', 'ab', 'ba', 'abab'], 'ab'),
    ]
    for n in (3, 5, 8, 10, 14):
        for _ in range(3):
            alpha = 'abcd'
            tests.append(fmt([rw(alpha, 1, 5) for _ in range(n)], rw(alpha, 1, 8)))
    for _ in range(3):
        tests.append(fmt([rw('abcdefghijklmnopqrstuvwxyz', 1, 6) for _ in range(10)], rw('abcdefghijklmnopqrstuvwxyz', 5, 14)))
    letters = 'abcdefghijklmnopqrstuvwxyz'
    tests.append(fmt([rw(letters, 1, 15) for _ in range(100000)], rw(letters, 100, 100)))
    tests.append(fmt([rw('abcd', 8, 15) for _ in range(40000)], rw('abcd', 100, 100)))
    tests.append(fmt([rw('abcde', 1, 15) for _ in range(100000)], rw('abcde', 30, 30)))
    return tests

